import{z as A,x as B,o as r,c as d,q as n,j as s,D as e,d as t,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"影子分页对照","description":"","frontmatter":{"title":"影子分页对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shadow-paging.md","filePath":"cs/shadow-paging.md","lastUpdated":1791413859000}'),p={name:"cs/shadow-paging.md"};function C(D,a,h,m,u,c){const o=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="影子分页对照" tabindex="-1">影子分页对照 <a class="header-anchor" href="#影子分页对照" aria-label="Permalink to &quot;影子分页对照&quot;">​</a></h1><div class="epigraph"><p>影子分页写新页并切换根：提交即新树可见，无需 redo 前滚。随机写与大目录更新是代价，现代 OLTP 主路径仍是 WAL 原地。</p><footer>—— 据 Lorie 影子分页；Gray and Reuter 对照；SQLite 回滚模式点名</footer></div><p><a href="/cs/logging-granularity">上一课</a>选了记什么。本课对照<strong>不原地更新</strong>的恢复：影子分页（shadow paging）。主干 WAL 是主路径；进阶用对照理解为何 ARIES 赢在随机 I/O 与细粒度。组提交下一课把 WAL 刷盘摊掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每页有当前与影子。事务写时拷页到新位置（COW），修改页表（或文件 inode 树）。提交：原子切换根指针（一次 I/O）。崩溃：根仍指旧树，新页丢弃。缺口是<strong>页表本身很大</strong>：更新一条索引可能级联大量目录页，写放大；难以 steal 单页而不暴露。并发：两事务 COW 同一页要合并。</p><p>SQLite 历史上 rollback journal / WAL 模式切换，是影子与日志在嵌入式上的产品对照。LMDB 一类 COW B+ 也是影子亲戚。</p><p><span class="marginnote">数字实例：提交只需 fsync 一次根指针，看起来便宜；但一个 8 KB 页哪怕只改了 100 字节，也得整页另写 8 KB——写放大约 80 倍，B+ 树上层目录页还会级联 COW。这就是大型 OLTP 弃用它的第一原因。</span></p><p><span class="marginnote">Raymond Lorie 影子分页。Gray and Reuter 分析为何大型系统偏 WAL。本课不是教「用影子替换 InnoDB」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：跟随当前根。写：分配新页号，拷旧，改，更新父（可能再 COW）。提交：fsync 新页与新根。检查点：可丢弃不可达旧页当 GC——与 MVCC 版本回收神似，粒度为页。</p><p>与 WAL 混合：写前日志仍可有，影子管页原子。现代常用 WAL+原地+doublewrite，少用纯影子。</p>',11)),(r(),s(l,null,{default:e(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%E6%A0%91%22%5D%20--%3E%20COW%5B%22%E5%86%99%E6%97%B6%E6%8B%B7%E9%A1%B5%22%5D%0A%20%20COW%20--%3E%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%0A%20%20NEW%20--%3E%20COM%5B%22%E5%8E%9F%E5%AD%90%E5%88%87%E6%8D%A2%E6%A0%B9%22%5D%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20OLD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"优点：恢复快（几乎不用 redo 长扫描），实现直观。缺点：随机分配页破坏聚簇、碎片、并发粒度粗、目录更新重。LSM 不可变文件+元数据指针切换，是文件级影子，吸收了「切换根」思想而把随机写变成顺序文件。",-1)),a[5]||(a[5]=E("p",null,"ARIES 用顺序日志换随机数据页延迟写，与影子的随机新页对偶。",-1)),(r(),s(l,null,{default:e(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CR%5B%22%E5%B4%A9%E6%BA%83%E5%90%8E%E9%87%8D%E5%90%AF%22%5D%20--%3E%20Q%7B%22%E9%87%87%E7%94%A8%E5%93%AA%E7%A7%8D%E6%9C%BA%E5%88%B6%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%BD%B1%E5%AD%90%E5%88%86%E9%A1%B5%7C%20R%5B%22%E8%AF%BB%E6%A0%B9%E6%8C%87%E9%92%88%E6%8C%87%E5%90%91%E5%93%AA%E6%A3%B5%E6%A0%91%22%5D%0A%20%20R%20--%3E%20A%5B%22%E6%96%B0%E6%A0%91%E5%AE%8C%E6%95%B4%E5%8D%B3%E5%B7%B2%E6%8F%90%E4%BA%A4%2C%20%E5%90%A6%E5%88%99%E5%BC%83%E7%94%A8%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%87%A0%E4%B9%8E%E6%97%A0%E9%9C%80%20redo%20%E6%89%AB%E6%8F%8F%22%5D%0A%20%20Q%20--%3E%7CWAL%2B%E5%8E%9F%E5%9C%B0%7C%20L%5B%22%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E8%B5%B7%E5%89%8D%E6%BB%9A%20redo%22%5D%0A%20%20L%20--%3E%20U%5B%22%E9%87%8D%E6%94%BE%E6%97%A5%E5%BF%97%E5%B0%BE%E5%88%B0%E4%B8%80%E8%87%B4%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：影子分页像编辑器的「另存为」——所有修改写进一份新副本，保存（提交）只是把快捷方式指过去；崩溃最多丢掉那份没被指到的新副本，原文件完好无损。所以它恢复极快，快在「根本不需要修复」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲组提交。也不把 ZFS CoW 当数据库事务。RTO 下一课之后量化。</p><p>后课默认：大型并发库用 WAL+ARIES；影子/COW 出现在嵌入式或文件级元数据。组提交：多事务共享一次 fsync。</p><p>影子的原子单位是根切换；WAL 的原子单位是日志尾。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子 COW+切根，恢复简单，随机写与目录放大差。</li><li>LSM/文件元数据吸收了切根思想。</li><li>组提交下一课：摊掉 WAL 的 fsync。</li><li>出处：Lorie；Gray and Reuter；SQLite/LMDB 对照。</li></ul>',7))])}const g=A(p,[["render",C]]);export{f as __pageData,g as default};
